1	import 'package:dio/dio.dart';
2	import 'package:flutter_dotenv/flutter_dotenv.dart';
3	import 'package:flutter_secure_storage/flutter_secure_storage.dart';
4	import 'package:get_it/get_it.dart';
5	
6	import '../network/access_token_provider.dart';
7	import '../network/api_client.dart';
8	import '../network/header_interceptor.dart';
9	import '../network/retry_interceptor.dart';
10	import '../network/url_builder.dart';
11	
12	/// The project's single `get_it` instance — exactly one DI container exists
13	/// (architecture spine). Every feature's `registerXFeature()` registers
14	/// through this same `sl`, never a second container.
15	final sl = GetIt.instance;
16	
17	/// Bootstraps core infrastructure: loads `.env`, then registers
18	/// `FlutterSecureStorage`, `Dio` (configured with the header + retry
19	/// interceptors) and `ApiClient` through `sl` — the `dio` +
20	/// `flutter_secure_storage` + `get_it` integration spike this story proves
21	/// before anything else is built on top of it.
22	Future<void> setupCoreDependencies() async {
23	  await dotenv.load(fileName: '.env');
24	
25	  final functionsBaseUrl = dotenv.get('FUNCTIONS_BASE_URL');
26	  final supabaseAnonKey = dotenv.get('SUPABASE_ANON_KEY');
27	
28	  sl.registerLazySingleton<FlutterSecureStorage>(
29	    () => const FlutterSecureStorage(),
30	  );
31	
32	  sl.registerLazySingleton<AccessTokenProvider>(
33	    () => SecureStorageAccessTokenProvider(sl<FlutterSecureStorage>()),
34	  );
35	
36	  sl.registerLazySingleton<UrlBuilder>(() => UrlBuilder(functionsBaseUrl));
37	
38	  sl.registerLazySingleton<Dio>(() {
39	    final dio = Dio(
40	      BaseOptions(
41	        // Design note (docs/input is silent on exact numbers): a stalled
42	        // connection must still fail instead of hanging indefinitely.
43	        connectTimeout: const Duration(seconds: 10),
44	        receiveTimeout: const Duration(seconds: 30),
45	        sendTimeout: const Duration(seconds: 30),
46	      ),
47	    );
48	    dio.interceptors.add(
49	      HeaderInterceptor(
50	        anonKey: supabaseAnonKey,
51	        accessTokenProvider: sl<AccessTokenProvider>(),
52	      ),
53	    );
54	    dio.interceptors.add(RetryInterceptor(dio));
55	    return dio;
56	  });
57	
58	  sl.registerLazySingleton<ApiClient>(
59	    () => ApiClient(dio: sl<Dio>(), urlBuilder: sl<UrlBuilder>()),
60	  );
61	}
62	
63	/// Test/teardown helper — resets the single `get_it` instance so each test
64	/// bootstraps its own clean registrations.
65	Future<void> resetCoreDependencies() => sl.reset();
