1	import 'package:dio/dio.dart';
2	import 'package:flutter_test/flutter_test.dart';
3	import 'package:mocktail/mocktail.dart';
4	
5	import 'package:cerne/core/failure/failure.dart';
6	import 'package:cerne/core/network/api_client.dart';
7	import 'package:cerne/core/network/url_builder.dart';
8	
9	class MockDio extends Mock implements Dio {}
10	
11	void main() {
12	  const baseUrl = 'https://host.example.com';
13	
14	  late MockDio mockDio;
15	  late ApiClient apiClient;
16	  late RequestOptions requestOptions;
17	
18	  setUp(() {
19	    mockDio = MockDio();
20	    apiClient = ApiClient(dio: mockDio, urlBuilder: const UrlBuilder(baseUrl));
21	    requestOptions = RequestOptions(path: '$baseUrl/auth-signup');
22	  });
23	
24	  group('ApiClient — real send/mapping logic, mocked Dio', () {
25	    test('success response -> Right(data)', () async {
26	      final response = Response<Map<String, dynamic>>(
27	        requestOptions: requestOptions,
28	        statusCode: 200,
29	        data: {'id': 'abc123'},
30	      );
31	      when(
32	        () => mockDio.post<Map<String, dynamic>>(any(), data: any(named: 'data')),
33	      ).thenAnswer((_) async => response);
34	
35	      final result = await apiClient.post('auth-signup', data: {'a': 1});
36	
37	      expect(result.isRight(), isTrue);
38	      result.match(
39	        (_) => fail('expected Right'),
40	        (data) => expect(data, {'id': 'abc123'}),
41	      );
42	    });
43	
44	    test(
45	        'DioException with a {code, message} body maps to the matching '
46	        'Failure', () async {
47	      final dioError = DioException(
48	        requestOptions: requestOptions,
49	        response: Response(
50	          requestOptions: requestOptions,
51	          statusCode: 429,
52	          data: {
53	            'code': 'RATE_LIMITED',
54	            'message': 'Too many requests',
55	            'retryable': true,
56	          },
57	        ),
58	        type: DioExceptionType.badResponse,
59	      );
60	      when(
61	        () => mockDio.post<Map<String, dynamic>>(any(), data: any(named: 'data')),
62	      ).thenThrow(dioError);
63	
64	      final result = await apiClient.post('auth-signup', data: {'a': 1});
65	
66	      expect(result.isLeft(), isTrue);
67	      result.match(
68	        (failure) {
69	          expect(failure, isA<RateLimited>());
