13	class AuthCubit extends Cubit<AuthState> {
14	  AuthCubit(this._authRepository) : super(const AuthState());
15	
16	  final AuthRepository _authRepository;
17	
18	  /// Toggles login/signup — same screen, not a navigation (epics.md Story
19	  /// 1.3 AC). Keeps whatever the user already typed; clears any error from
20	  /// the previous mode's attempt.
21	  void toggleMode() {
22	    emit(
23	      AuthState(
24	        mode: state.mode == AuthMode.login ? AuthMode.signUp : AuthMode.login,
25	        email: state.email,
26	        password: state.password,
27	      ),
28	    );
29	  }
30	
31	  void emailChanged(String value) {
32	    emit(
33	      state.copyWith(
34	        email: value,
35	        clearEmailError: true,
36	        clearFormError: true,
37	      ),
38	    );
39	  }
40	
41	  void passwordChanged(String value) {
42	    emit(state.copyWith(password: value, clearFormError: true));
43	  }
