46	  /// submit *before* any round trip (epics.md Story 1.3 AC). Only once local
47	  /// validation passes does it call `auth-signup`/`auth-login` with exactly
48	  /// `{email, password}`, saving the access token (via the repository) before
49	  /// this resolves.
50	  Future<void> submit() async {
51	    if (state.isSubmitting) {
52	      return;
53	    }
54	
55	    final emailError = validateEmail(state.email);
56	    if (emailError != null) {
57	      emit(
58	        state.copyWith(emailError: emailError, clearFormError: true),
59	      );
60	      return;
