72	      state.copyWith(
73	        status: const ResourceLoading<Unit>(),
74	        clearEmailError: true,
75	        clearFormError: true,
76	      ),
77	    );
78	
79	    final result = state.mode == AuthMode.login
80	        ? await _authRepository.logIn(
81	            email: state.email,
82	            password: state.password,
83	          )
84	        : await _authRepository.signUp(
85	            email: state.email,
86	            password: state.password,
87	          );
